// Four-piece camera geometry follows the approved atlas, independently of other products.
const whole=' Entire bed, styled pillows and all duvet/sheet corners inside the frame, roughly 65-75% coverage with usable margins; normal 45-60 mm equivalent perspective, no wide-angle stretching.';
const close=' Contextual close view, requested detail roughly 50-65% of frame, with the named detail dominant and surrounding connected fabric visible. Other components may remain outside this crop; do not remove them from the setup or force a full-bed view.';
const structural=' Never copy sample colors, room or unselected crafts.';
const rules={
  side:['右斜侧','按参考图：床头在画面右上、床尾向左下延伸，45°斜侧全景；机位略高于床面、俯约20°，造型中的枕头和完整垂边入镜。','Approved RIGHT DIAGONAL composition: headboard toward upper-right, foot toward lower-left, near long bed side visible. Approximately 45-degree three-quarter view, gently elevated 20-degree downward tilt. ',true],
  relaxed:['左斜侧','按新参考图：床头在画面左上、床尾向右下延伸，45°斜侧全景；镜头拉远，保留自然堆褶、床头宽幅翻折和完整垂边。','Approved LEFT DIAGONAL composition: headboard toward upper-left, foot toward lower-right; opposite diagonal to right-diagonal. Approximately 45-degree three-quarter view, 20-degree downward tilt. Step back, keep natural broad rumpled folds and a soft head-end turnover. ',true],
  front:['正面全景','床尾中心正对床头，床头水平、左右平衡；轻微俯拍，完整床品和床侧、床尾垂边入镜。','Centered foot-end frontal full-bed view, horizontal headboard, balanced left/right edges, slight downward tilt. No oblique diagonal. ',true],
  top:['高位俯拍','床尾中心升高机位，约55°至65°斜俯拍；床头和造型中的枕头仍可见，床面纵向完整；不是90°垂直俯视。','Elevated centered foot-end view tilted downward about 55-65 degrees. Bed axis centered, headboard and upright pillow faces remain visible above the complete bed surface. NOT vertical 90-degree overhead. ',true],
  left:['左侧全景','床头在画面左侧、床尾向右侧延伸，近乎侧面全景，长侧边为主，轻微俯拍。','Near lateral whole-bed profile, headboard at frame LEFT and foot at frame RIGHT, long side dominant, approximately 75-85 degrees from bed axis with gentle downward tilt. ',true],
  right:['右侧全景','床头在画面右侧、床尾向左侧延伸，与左侧全景相反，近乎侧面全景，轻微俯拍。','Opposite near lateral whole-bed profile, headboard at frame RIGHT and foot at frame LEFT, long side dominant, approximately 75-85 degrees from bed axis with gentle downward tilt. Rephotograph, never mirror the print. ',true],
  wide:['斜俯全景','从高位斜前方俯拍，约45°至55°俯角；完整整床、床头和周围少量地面可见，主体清楚，不是远距离小床图。','High diagonal full-bed photograph, headboard upper-right and foot lower-left, downward tilt about 45-55 degrees. Whole bed and a modest surrounding floor area visible; product remains prominent, not a tiny bed in a distant room. ',true],
  low:['床面近景','机位略高于床面，斜侧近拍造型中的枕头、床头翻折与自然堆褶；下半床可出画，不采用床垫下方仰拍。','Medium upper-bed diagonal view, camera slightly ABOVE mattress with a gentle downward tilt. Frame the styled pillows, natural head-end turnover and rumpled upper duvet surface. Lower bed may exit frame. NOT below-mattress upward low-angle photography. ',false],
  reverse:['翻折看反面','斜侧中近景：造型中的枕头、同一被套的宽幅真实翻回和下方正面，侧边可见独立床单；翻折不新增被子或床尾巾。','Diagonal medium upper-bed view showing styled pillows and a broad soft head-end turnover of the SAME duvet. Actual reverse is exposed above its front panel; the separate sheet remains underneath. No extra duvet or runner. ',false],
  foot:['床尾近景','近拍床尾下半部和一个自然垂角：上方被套外缘、下方独立床单、床架及地面层次清楚；枕头可出画。','Diagonal close view of lower bed and one hanging FOOT CORNER: duvet finished hem above separate sheet, bed support and a little floor. The corner, layered hems and natural drape dominate; no requirement to include pillows or the full foot width. ',false],
  pillowclose:['枕套特写','中近景展示当前造型中的睡枕及枕套边缘，可自然转向露出背片，保留少量床面；不限定数量或床头位置。','Medium close photograph focused on the styled sleeping pillows and their pillowcase edges, with a little connected bedding foreground. Follow their current creative placement; do not relocate them to the head or fix the count. An actual reverse may be naturally visible. ',false],
  detail:['面料特写','贴近被套正面拍织纹与柔软浅褶，周围仍是连续布面，不展示整床或枕套。','Close textile view of the duvet FRONT weave and soft shallow natural creases, oblique 25-40-degree angle to local cloth plane. Connected surface fills the image; no whole bed or pillow focus. Texture follows user priority, not sample cotton automatically. ',false],
  drape:['床边垂坠','从长侧边近拍：床面向垂边过渡，上层被套与下层床面部件分别收边，保留床架参照。','Medium side-edge view along a long bed side, show top-to-hanging transition, duvet hem ABOVE the independent bed-surface textile and a little bed support. Gravity-settled soft folds, separate edges; fitted/skirt variants follow selected construction. ',false],
  headclose:['床头近景','略高于床面的斜侧中近景，造型中的枕头和被套床头翻折为主，保留上半床面。','Gently elevated diagonal HEAD-END medium close view. styled pillows and the soft broad duvet turnover dominate, with surrounding upper duvet surface; lower bed outside crop. ',false],
  foldleft:['左侧翻折','近拍被套一侧宽幅翻折，反面布、真实外缘接缝和下层正面清楚；枕头与整床不必入镜。','Oblique close photograph of one SIDE of the turned-back duvet: broad reverse panel falls diagonally from upper-right toward lower-left over a separate front surface. Real finished joining edge separates the two sewn panels. No forced whole-bed view. ',false],
  foldright:['右侧翻折','从相反一侧近拍床头翻折，前景是被套正面褶皱，后方露真实反面，枕头可部分入镜。','Opposite-side oblique close photograph of head-end turnover: front duvet folds in foreground, broad actual reverse strip behind, turning edge receding diagonally toward upper-left. Pillow edges may be naturally partially visible. ',false],
  pillowedge:['枕套接缝','近拍单只枕套柔软外缘接缝及邻接布面，枕芯略撑起边角，后方床单只是独立背景。','Close photograph of ONE pillowcase supported corner and actual sewn outer joining seam, softly filled rounded edge with nearby front/reverse fabric and a little independent sheet background. No whole pair or whole bed required. ',false],
  sheetcorner:['床单垂角','近拍普通床单从床垫顶面越边后自然垂落的角部，下摆独立，旁边被套是另一个部件；其他床面款式按选择。','Medium close photograph of one bed-surface textile CORNER. For flat sheet, a single thin sheet flows from mattress top over edge into a loose hanging corner and its own hem; adjacent duvet remains independent. For selected fitted/skirt variant, show its actual corner structure instead. ',false],
  reverseclose:['翻面接缝','近拍同一被套翻回处的真实正反接合线，两侧分别是所属裁片，缝线不跨面串花，背景保留连续布面。','Close photograph of the SAME duvet true front-reverse sewn perimeter at an actual turnover: two separate panels meet along the finished seam, each print ends at its own sewn edge. No motif continuation across the sewn junction, even if A and B use the same print; ordinary folds within a panel remain continuous. ',false],
  bedupper:['斜侧近景','从另一斜侧略高于床面拍上半床，造型中的枕头、宽幅翻折和正面布自然浅褶同框；不是高位整床俯拍。','Opposite diagonal UPPER-BED medium close composition, headboard toward upper-left, front duvet surface towards lower-right. Slightly above mattress, gentle 15-25-degree downward tilt, show styled pillows, broad head-end turnover and connected duvet surface. NOT high 60-degree full-bed overhead. ',false]
};
export const setCameraDirections=Object.fromEntries(Object.entries(rules).map(([id,[name,zh,prompt,full]])=>[id,{name,zh:zh+'花型、A/B分面、面料和工艺按用户选择；参考图只指导机位与造型。',prompt:prompt+(full?whole:close)+structural,full}]));
export function setCameraFraming(angle){return setCameraDirections[angle]?.full?' FOUR-PIECE FRAMING: retain styled pillows and complete selected bedding outline with comfortable editing margins. Keep the requested camera tilt and diagonal orientation.':' FOUR-PIECE DETAIL FRAMING: keep the named local detail and its surrounding connected cloth; styled pillows and lower bed may naturally lie outside the crop. Never change to a full-bed shot to include them.';}
